from typing import List, Dict, Any
import sys
import json

def filter_rows(rows: List[Dict[str, str]], column: str, value: str) -> List[Dict[str, str]]:
    """Filter rows by column value."""
    return [row for row in rows if row.get(column) == value]

def select_columns(rows: List[Dict[str, str]], columns: List[str]) -> List[Dict[str, str]]:
    """Return only specified columns in each row."""
    return [ {col: row.get(col, "") for col in columns} for row in rows ]

def sort_rows(rows: List[Dict[str, str]], column: str) -> List[Dict[str, str]]:
    """Sort rows based on column."""
    return sorted(rows, key=lambda row: row.get(column, ""))

def output_data(rows: List[Dict[str, str]], fmt: str = "csv") -> None:
    """Output the rows in the requested format."""
    if fmt == "json":
        print(json.dumps(rows, indent=2))
    elif fmt == "table":
        try:
            from tabulate import tabulate
            if rows:
                print(tabulate(rows, headers="keys", tablefmt="github"))
            else:
                print("(no data)")
        except ImportError:
            print("tabulate is not installed. Use 'pip install tabulate' or use --format csv/json.", file=sys.stderr)
    else:
        if not rows:
            return
        import csv
        writer = csv.DictWriter(sys.stdout, fieldnames=rows[0].keys())
        writer.writeheader()
        writer.writerows(rows)
